import { extrairTextos } from './regras';

const MODELO = '@cf/meta/llama-3.3-70b-instruct-fp8-fast';
/** Em lotes grandes o modelo perde a criatividade e cai em frases genéricas; lotes pequenos rendem melhor. */
const POR_PEDIDO = 6;

const TEMAS = [
  'cozinha e receitas', 'animais de estimação', 'viagens e passeios', 'esportes', 'natureza e clima',
  'lembranças de infância', 'vida na cidade', 'vida no interior', 'música e festas', 'escola e aprendizado',
  'tecnologia no dia a dia', 'família e amigos', 'hobbies e artesanato', 'praia e férias', 'cinema e livros',
  'feira e mercado', 'transporte e trânsito', 'jardim e horta', 'fim de semana', 'pequenos imprevistos engraçados',
];

const instrucoes = (temas: string[]) => `Escreva ${POR_PEDIDO} textos originais em português do Brasil, para treino de digitação.

Cada texto conta uma pequena cena do cotidiano, com algum detalhe concreto, curioso ou bem-humorado.
Evite frases genéricas como "Gatos são carinhosos" ou "Viajar é divertido".

Regras:
- Exatamente duas frases por texto, com 25 a 32 palavras no total.
- Linguagem leve, para todos os públicos. Acentos e pontuação corretos.
- Sem nomes de pessoas reais, marcas, política, religião, violência, números ou datas.
- Sem palavras que indiquem o gênero de quem narra (evite "cansado/cansada" em primeira pessoa).
- Um assunto diferente por texto, entre: ${temas.join(', ')}.

Exemplos do estilo esperado:
O controle remoto sumiu de novo, e ninguém lembra quem viu por último. Depois de revirar a sala inteira, ele apareceu dentro da geladeira, ao lado do queijo.
Às sextas, a padaria da esquina faz pão de queijo com o dobro de queijo. A fila começa antes das sete, e quem chega depois das oito só sente o cheiro.

Responda apenas com os textos, um por linha, sem numeração, sem aspas, sem linhas em branco e sem comentários.`;

async function pedir(ai: Ai, temas: string[]): Promise<string[]> {
  const resposta = await ai.run(MODELO, {
    messages: [{ role: 'user', content: instrucoes(temas) }],
    max_tokens: 1200,
    temperature: 0.9,
  });
  return extrairTextos((resposta as { response?: string }).response ?? '');
}

const criterios = (textos: string[]) => `Você é um editor rigoroso de textos em português do Brasil. Avalie cada texto abaixo.

Aprove somente se TODOS os critérios forem atendidos:
1. Ortografia, acentuação e concordância corretas, sem nenhuma palavra em outro idioma. Leia palavra por palavra:
   reprove erros como "sucosos" (o certo é "suculentos"), "agua" sem acento ou termos em inglês como "favorite", "brunch" ou "children".
2. Soa natural, como algo que uma pessoa escreveria.
3. Tem um detalhe concreto, curioso ou bem-humorado; não é só uma descrição genérica (como "O parque é bonito e as pessoas se divertem").

${textos.map((t, i) => `${i + 1}. ${t}`).join('\n')}

Responda apenas com os números dos textos aprovados, separados por vírgula. Se nenhum for aprovado, responda 0.`;

/** Segunda passada: o modelo, no papel de editor, reprova textos com erros ou sem graça. */
async function revisar(ai: Ai, textos: string[]): Promise<string[]> {
  if (!textos.length) return [];
  const resposta = await ai.run(MODELO, {
    messages: [{ role: 'user', content: criterios(textos) }],
    max_tokens: 100,
    temperature: 0,
  });
  const aprovados = new Set(((resposta as { response?: string }).response ?? '').match(/\d+/g)?.map(Number));
  return textos.filter((_, i) => aprovados.has(i + 1));
}

/** Gera textos em pedidos paralelos, cada um com temas diferentes, e devolve só os aprovados na revisão. */
export async function gerarTextos(ai: Ai, quantidade: number): Promise<string[]> {
  const temas = [...TEMAS].sort(() => Math.random() - 0.5);
  const pedidos = Math.ceil(quantidade / POR_PEDIDO);
  const lotes = await Promise.allSettled(
    Array.from({ length: pedidos }, (_, i) => pedir(ai, temas.slice((i * 4) % TEMAS.length, (i * 4) % TEMAS.length + 4))),
  );
  // Um pedido que falha não derruba os outros.
  const candidatos = [...new Set(lotes.flatMap((l) => (l.status === 'fulfilled' ? l.value : [])))];
  return revisar(ai, candidatos);
}
