import { dataHoje, fraseDoDia } from './desafio';
import { gerarTextos } from './gerar';
import { avaliarEnvio, JOGADOR, validarApelido } from './regras';

interface Env {
  DB: D1Database;
  AI: Ai;
  ORIGENS: string; // origens permitidas, separadas por vírgula
}

const JA_JOGOU = 'Você já fez o desafio de hoje. Volte amanhã!';
const TEXTOS_POR_DIA = 20;

/**
 * Frase do desafio do dia. Se a geração automática ainda não rodou ou falhou, usa um texto do acervo
 * que nunca foi desafio e, em último caso, a reserva fixa. Uma vez gravada, fica igual o dia inteiro.
 */
async function desafioDoDia(db: D1Database, data: string): Promise<string> {
  await db
    .prepare(`INSERT OR IGNORE INTO desafios (data, frase)
              SELECT ?, COALESCE((SELECT texto FROM textos WHERE texto NOT IN (SELECT frase FROM desafios) ORDER BY RANDOM() LIMIT 1), ?)`)
    .bind(data, fraseDoDia(data))
    .run();
  return (await db.prepare('SELECT frase FROM desafios WHERE data = ?').bind(data).first<string>('frase'))!;
}

/** Roda uma vez por dia, logo após a meia-noite: gera o desafio do dia e novos textos para o treino. */
async function gerarDoDia(env: Env) {
  const data = dataHoje();
  const textos = await gerarTextos(env.AI, TEXTOS_POR_DIA + 1);

  // O primeiro texto que nunca foi desafio vira o desafio do dia; os outros vão para o acervo do treino.
  const usado = (t: string) => env.DB.prepare('SELECT 1 FROM desafios WHERE frase = ?').bind(t).first();
  let desafio: string | undefined;
  for (const t of textos) if (!desafio && !(await usado(t))) desafio = t;
  const treino = textos.filter((t) => t !== desafio);

  if (desafio) await env.DB.prepare('INSERT OR IGNORE INTO desafios (data, frase) VALUES (?, ?)').bind(data, desafio).run();
  if (treino.length) {
    await env.DB.batch(treino.map((t) => env.DB.prepare('INSERT OR IGNORE INTO textos (texto) VALUES (?)').bind(t)));
  }
  console.log(`${data}: ${textos.length} textos gerados.`);
}

async function ranking(db: D1Database, data: string, jogador: string | null) {
  const { results: top } = await db
    .prepare('SELECT apelido, ppm, precisao FROM resultados WHERE data = ? ORDER BY ppm DESC, criado_em LIMIT 10')
    .bind(data)
    .all();
  const total = await db.prepare('SELECT COUNT(*) AS n FROM resultados WHERE data = ?').bind(data).first<number>('n');
  const meu = jogador
    ? await db
      .prepare(`SELECT apelido, ppm, precisao,
                  (SELECT COUNT(*) FROM resultados r WHERE r.data = s.data AND r.ppm > s.ppm) + 1 AS posicao
                FROM resultados s WHERE data = ? AND jogador = ?`)
      .bind(data, jogador)
      .first()
    : null;
  return { data, total, top, meu };
}

async function tratar(req: Request, env: Env): Promise<[unknown, number]> {
  const url = new URL(req.url);
  const hoje = dataHoje();

  if (url.pathname === '/teste-ia') { // TEMP
    return [{ aceitos: await gerarTextos(env.AI, Number(url.searchParams.get('n')) || TEXTOS_POR_DIA + 1) }, 200];
  }

  if (req.method === 'GET') {
    if (url.pathname === '/desafio') return [{ data: hoje, frase: await desafioDoDia(env.DB, hoje) }, 200];

    if (url.pathname === '/texto') {
      const excluir = Number(url.searchParams.get('excluir')) || 0;
      const texto = await env.DB.prepare('SELECT id, texto FROM textos WHERE id != ? ORDER BY RANDOM() LIMIT 1').bind(excluir).first();
      return texto ? [texto, 200] : [{ erro: 'Acervo vazio.' }, 404];
    }

    if (url.pathname === '/ranking') {
      const jogador = url.searchParams.get('jogador');
      return [await ranking(env.DB, hoje, jogador && JOGADOR.test(jogador) ? jogador : null), 200];
    }
  }

  if (req.method !== 'POST') return [{ erro: 'Não encontrado.' }, 404];
  const corpo = await req.json<{ jogador?: unknown; apelido?: unknown; precisao?: unknown }>();
  const jogador = typeof corpo.jogador === 'string' && JOGADOR.test(corpo.jogador) ? corpo.jogador : null;
  if (!jogador) return [{ erro: 'Jogador inválido.' }, 400];

  const jaJogou = () => env.DB.prepare('SELECT 1 FROM resultados WHERE data = ? AND jogador = ?').bind(hoje, jogador).first();

  if (url.pathname === '/inicio') {
    if (await jaJogou()) return [{ erro: JA_JOGOU }, 409];
    // Só a primeira chamada do dia grava a hora; as seguintes mantêm o relógio original.
    await env.DB.prepare('INSERT OR IGNORE INTO inicios (data, jogador, inicio) VALUES (?, ?, ?)').bind(hoje, jogador, Date.now()).run();
    return [{ ok: true }, 200];
  }

  if (url.pathname === '/resultado') {
    const agora = Date.now();
    const inicio = await env.DB.prepare('SELECT inicio FROM inicios WHERE data = ? AND jogador = ?').bind(hoje, jogador).first<number>('inicio');
    if (inicio === null) return [{ erro: 'Desafio não iniciado.' }, 400];

    const apelido = validarApelido(corpo.apelido);
    if ('erro' in apelido) return [apelido, 400];
    const avaliacao = avaliarEnvio(await desafioDoDia(env.DB, hoje), inicio, agora, corpo.precisao);
    if ('erro' in avaliacao) return [avaliacao, 400];

    const { meta } = await env.DB
      .prepare('INSERT OR IGNORE INTO resultados (data, jogador, apelido, ppm, precisao) VALUES (?, ?, ?, ?, ?)')
      .bind(hoje, jogador, apelido.apelido, avaliacao.ppm, avaliacao.precisao)
      .run();
    if (!meta.changes) return [{ erro: JA_JOGOU }, 409];
    return [await ranking(env.DB, hoje, jogador), 201];
  }

  return [{ erro: 'Não encontrado.' }, 404];
}

export default {
  async fetch(req, env) {
    const origem = req.headers.get('Origin') ?? '';
    const cabecalhos = {
      'Content-Type': 'application/json; charset=utf-8',
      'Access-Control-Allow-Origin': env.ORIGENS.split(',').includes(origem) ? origem : '',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type',
      Vary: 'Origin',
    };
    if (req.method === 'OPTIONS') return new Response(null, { status: 204, headers: cabecalhos });

    try {
      const [corpo, status] = await tratar(req, env);
      return new Response(JSON.stringify(corpo), { status, headers: cabecalhos });
    } catch (e) {
      console.error(e);
      return new Response(JSON.stringify({ erro: 'Erro interno. Tente de novo em instantes.' }), { status: 500, headers: cabecalhos });
    }
  },

  async scheduled(_evento, env, ctx) {
    ctx.waitUntil(gerarDoDia(env));
  },
} satisfies ExportedHandler<Env>;
